    assert.ok(manifest.entry[variant].startsWith(packagePrefix + '@proofscript/compiler/'));
    assert.ok(seen.has(manifest.entry[variant]), 'PSC1_EXECUTABLE_ENTRY');
  }
  return manifest;
}

